import{_ as o,c as r,o as i,ag as n,j as a,a as s,t as e}from"./chunks/framework.Bkod66qp.js";const _=JSON.parse('{"title":"AI‑INSTR (Central Instruction for AI / LLM Pipelines)","description":"","frontmatter":{},"headers":[],"relativePath":"ai_instr.md","filePath":"ai_instr.md"}'),d={name:"ai_instr.md"};function h(l,t,c,u,g,p){return i(),r("div",null,[t[1]||(t[1]=n(`<h1 id="ai‐instr-central-instruction-for-ai-llm-pipelines" tabindex="-1">AI‑INSTR (Central Instruction for AI / LLM Pipelines) <a class="header-anchor" href="#ai‐instr-central-instruction-for-ai-llm-pipelines" aria-label="Permalink to &quot;AI‑INSTR (Central Instruction for AI / LLM Pipelines)&quot;">​</a></h1><blockquote><p><strong>이 파일은 모든 문서가 공통으로 참조하는 &quot;중앙 관리용&quot; 규칙집입니다.</strong><br> 이제부터 개별 문서는 <strong>하나의 HTML 주석</strong>만 남기고 이 파일을 참조합니다.</p></blockquote><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- AI-INSTR-REF: /_ai/AI-INSTR.md --&gt;</span></span></code></pre></div><p>위와 같이 <strong>파일 경로만</strong> 넣으면 됩니다. 버전 앵커·YAML 키 모두 필요 없습니다.</p><hr><h2 id="_0-적용-대상-참조-방식" tabindex="-1">0. 적용 대상 &amp; 참조 방식 <a class="header-anchor" href="#_0-적용-대상-참조-방식" aria-label="Permalink to &quot;0. 적용 대상 &amp; 참조 방식&quot;">​</a></h2><table tabindex="0"><thead><tr><th>구분</th><th>내용</th></tr></thead><tbody><tr><td><strong>적용 대상</strong></td><td>VitePress로 빌드되는 모든 Markdown/Raw HTML 문서, 이후 AI·챗봇·벡터DB에 투입되는 동일 원본</td></tr><tr><td><strong>참조 표식(필수)</strong></td><td><code>&lt;!-- AI-INSTR-REF: /_ai/AI-INSTR.md --&gt;</code> <em>(HTML 주석 한 줄)</em></td></tr><tr><td><strong>참조 표식 위치</strong></td><td>YAML 아래 또는 문서 상단 아무 곳. 렌더링에 영향 없음</td></tr><tr><td><strong>버전 관리</strong></td><td>이 파일 내부에서만 관리. 참조 표식은 <strong>항상 동일</strong></td></tr></tbody></table><blockquote><p>문서 수백 개가 있어도 <strong>표식은 한 번만 삽입</strong>하면 끝. AI‑INSTR가 업데이트돼도 문서를 다시 고칠 필요 없습니다.</p></blockquote><hr><h2 id="_1-목적" tabindex="-1">1. 목적 <a class="header-anchor" href="#_1-목적" aria-label="Permalink to &quot;1. 목적&quot;">​</a></h2><ol><li>문서 구조·메타데이터·표기 규칙을 AI/LLM 파이프라인이 <strong>일관되게 해석</strong>하도록 통합 관리한다.</li><li>VitePress 렌더링과 AI 파싱 간 <strong>숨김/표시/색인 정책</strong>을 통일한다.</li><li>변환·빌드·검색 파이프라인에서 생길 수 있는 <strong>오류·충돌의 우선 처리 규칙</strong>을 정의한다.</li></ol><hr><h2 id="_2-파싱-우선순위" tabindex="-1">2. 파싱 우선순위 <a class="header-anchor" href="#_2-파싱-우선순위" aria-label="Permalink to &quot;2. 파싱 우선순위&quot;">​</a></h2><ol><li><strong>YAML Front Matter</strong> → 파싱 후 본문에도 보존</li><li><strong>Markdown 본문</strong></li><li><strong>Raw HTML 블록</strong> (정보성 유지, 순수 스타일은 AI 요약에서 제외 가능)</li><li><strong>무시 토큰</strong>(<code>AI-IGNORE-START/END</code>) 사이 영역은 완전 무시</li></ol><p>파싱 실패 시: 가능한 범위만 파싱하고 로그에 남긴다.</p><hr><h2 id="_3-yaml-규칙" tabindex="-1">3. YAML 규칙 <a class="header-anchor" href="#_3-yaml-규칙" aria-label="Permalink to &quot;3. YAML 규칙&quot;">​</a></h2><ul><li>최상단 <code>---</code> … <code>---</code> 블록 하나만 허용.</li><li>모든 키/값을 그대로 보존·색인한다.</li><li>배열/객체 구조 유지.</li><li>주석은 <code>#</code> 사용. YAML 밖 설명 문장은 넣지 않는다.</li></ul><hr><h2 id="_4-헤더·클래스-규칙" tabindex="-1">4. 헤더·클래스 규칙 <a class="header-anchor" href="#_4-헤더·클래스-규칙" aria-label="Permalink to &quot;4. 헤더·클래스 규칙&quot;">​</a></h2><ul><li>헤더 예: <code>## 제1조 (목적) {#article1 .sr-only}</code><br><code>{#id .class}</code> 문법(markdown‑it‑attrs)을 따른다.</li><li>숨김/표시 클래스:<table tabindex="0"><thead><tr><th>클래스</th><th>역할</th><th>렌더링</th><th>색인/요약</th></tr></thead><tbody><tr><td><code>.sr-only</code></td><td>시각적 숨김, 스크린리더 표시</td><td>숨김</td><td>포함</td></tr><tr><td><code>.toc-only</code></td><td>ToC 전용</td><td>숨김</td><td>제외</td></tr></tbody></table></li><li>그 외 클래스·style 속성은 기본 무시. 단 <code>.sr-only</code>, <code>.toc-only</code>는 예외.</li></ul><hr><h2 id="_5-조문-법령-구조-패턴" tabindex="-1">5. 조문(법령) 구조 패턴 <a class="header-anchor" href="#_5-조문-법령-구조-패턴" aria-label="Permalink to &quot;5. 조문(법령) 구조 패턴&quot;">​</a></h2><ol><li>숨김 헤더(목차용): <code>## 제n조 (제목) {#artN .sr-only}</code></li><li>본문 표제: <code>**제n조 (제목)**</code></li><li>조문 전문</li></ol><p>중복 텍스트 허용, 항/호 기호(①, 1., 가. 등) 유지.</p><hr><h2 id="_6-raw-html-처리" tabindex="-1">6. RAW HTML 처리 <a class="header-anchor" href="#_6-raw-html-처리" aria-label="Permalink to &quot;6. RAW HTML 처리&quot;">​</a></h2><ul><li>정보성 HTML은 삭제하지 않음.</li><li>순수 레이아웃/스타일용 DIV·SPAN은 AI 요약에서 제외 가능.</li><li>열려 있지 않은 태그가 있으면 가능하면 닫는다.</li></ul><hr><h2 id="_7-무시-토큰" tabindex="-1">7. 무시 토큰 <a class="header-anchor" href="#_7-무시-토큰" aria-label="Permalink to &quot;7. 무시 토큰&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AI-IGNORE-START</span></span>
<span class="line"><span>(이 구간은 검색·요약·QA에서 제외)</span></span>
<span class="line"><span>AI-IGNORE-END</span></span></code></pre></div><ul><li>중첩 금지.</li></ul><hr><h2 id="_8-청크-분할" tabindex="-1">8. 청크 분할 <a class="header-anchor" href="#_8-청크-분할" aria-label="Permalink to &quot;8. 청크 분할&quot;">​</a></h2><ul><li>권장 길이: 1 000–2 000 tokens.</li><li>분할 우선순위: (1) 조·항·호 → (2) 문단 → (3) 임의 분할.</li></ul><hr><h2 id="_9-오류·우선순위-규칙" tabindex="-1">9. 오류·우선순위 규칙 <a class="header-anchor" href="#_9-오류·우선순위-규칙" aria-label="Permalink to &quot;9. 오류·우선순위 규칙&quot;">​</a></h2><ol><li>YAML &gt; 무시토큰 &gt; 헤더/숨김 &gt; 기타 스타일</li><li>오류는 로그 후 가능한 범위 파싱.</li><li>충돌 시 <strong>이 파일의 최신 규칙</strong>을 우선.</li></ol><hr><h2 id="_10-버전-관리-내부용" tabindex="-1">10. 버전 관리 (내부용) <a class="header-anchor" href="#_10-버전-관리-내부용" aria-label="Permalink to &quot;10. 버전 관리 (내부용)&quot;">​</a></h2><ul><li>파일 상단에 <code>AI-INSTR vYYYY-MM-DD</code> 표기 + Change Log 추가.</li><li>과거 버전 섹션(예: <code>## v2025-07-24</code>)은 필요 시 유지.</li><li><strong>문서 참조 표식은 바꾸지 않는다</strong> → 업데이트 시에도 크롤러가 최신 내용을 자동 취득.</li></ul><hr><h2 id="_11-배포·접근-정책" tabindex="-1">11. 배포·접근 정책 <a class="header-anchor" href="#_11-배포·접근-정책" aria-label="Permalink to &quot;11. 배포·접근 정책&quot;">​</a></h2><ul><li><code>/docs/_ai/AI-INSTR.md</code> 처럼 모든 파이프라인이 접근 가능하도록 둔다.</li><li>외부 크롤러 차단 여부는 <code>robots.txt</code> 등으로 관리.</li></ul><hr><h2 id="_12-faq" tabindex="-1">12. FAQ <a class="header-anchor" href="#_12-faq" aria-label="Permalink to &quot;12. FAQ&quot;">​</a></h2><ul><li><strong>문서마다 버전 업데이트가 필요 없나요?</strong><br> 네. 모든 문서는 고정 문자열 <code>&lt;!-- AI-INSTR-REF: /_ai/AI-INSTR.md --&gt;</code> 만 유지하면 됩니다.</li><li><strong>YAML에 별도 키를 안 넣어도 되나요?</strong><br> 네. HTML 주석 한 줄이면 충분합니다.</li><li><strong>AI‑INSTR가 깨지면 어떻게 하나요?</strong><br> 파이프라인에서 fallback 규칙(예: 마지막 유효 버전 캐시)을 두세요.</li></ul><hr><h2 id="_13-담당자-체크리스트" tabindex="-1">13. 담당자 체크리스트 <a class="header-anchor" href="#_13-담당자-체크리스트" aria-label="Permalink to &quot;13. 담당자 체크리스트&quot;">​</a></h2>`,49)),a("blockquote",null,[a("p",null,[t[0]||(t[0]=a("strong",null,"문의/수정 요청",-1)),s(": 담당자 "+e(l.OWNER)+" ("+e(l.CONTACT)+")",1)])]),t[2]||(t[2]=a("hr",null,null,-1))])}const A=o(d,[["render",h]]);export{_ as __pageData,A as default};
